"use client";
import { useState } from "react";

export default function RegisterPage() {
  const [form, setForm] = useState({
    ownerName: "",
    email: "",
    phone: "",
    password: "",
    restaurantName: "",
    restaurantType: "",
    fullAddress: "",
    city: "",
    state: "",
    pincode: "",
    totalTables: "",
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");
    setLoading(true);

    try {
      const res = await fetch("/api/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });

      const data = await res.json();
      setLoading(false);

      if (!res.ok) {
        setMessage(data.error || "Registration failed");
      } else {
        setMessage("Restaurant Registered Successfully!");
      }
    } catch (err) {
      setLoading(false);
      setMessage("Something went wrong");
    }
  };

  return (
    <section className="min-h-screen flex items-center justify-center px-6 py-12 bg-gray-50">
      <div className="max-w-3xl w-full bg-white rounded-3xl shadow-xl p-10 border border-gray-200">

        {/* Heading */}
        <h2 className="text-4xl font-bold text-center mb-8 bg-clip-text text-transparent bg-gradient-to-r from-[#D4AF37] to-[#FFD700]">
          Register Your Restaurant
        </h2>

        {/* Form */}
        <form onSubmit={handleSubmit} className="space-y-6">

          {/* Owner Details */}
          <div>
            <h3 className="text-xl font-semibold mb-2 text-gray-700">Owner Details</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <input type="text" name="ownerName" placeholder="Owner Name" onChange={handleChange} required className="input" />
              <input type="email" name="email" placeholder="Email" onChange={handleChange} required className="input" />
              <input type="text" name="phone" placeholder="Phone Number" onChange={handleChange} required className="input" />
              <input type="password" name="password" placeholder="Password" onChange={handleChange} required className="input" />
            </div>
          </div>

          {/* Restaurant Details */}
          <div>
            <h3 className="text-xl font-semibold mb-2 text-gray-700">Restaurant Details</h3>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <input type="text" name="restaurantName" placeholder="Restaurant Name" onChange={handleChange} required className="input" />

              <select name="restaurantType" onChange={handleChange} required className="input">
                <option value="">Restaurant Type</option>
                <option value="Cafe">Cafe</option>
                <option value="Fine Dining">Fine Dining</option>
                <option value="Casual Dining">Casual Dining</option>
                <option value="Bar">Bar</option>
                <option value="Bakery">Bakery</option>
                <option value="Restaurant">Restaurant</option>
              </select>

              <input type="text" name="fullAddress" placeholder="Full Address" onChange={handleChange} required className="input md:col-span-2" />

              <input type="text" name="city" placeholder="City" onChange={handleChange} required className="input" />
              <input type="text" name="state" placeholder="State" onChange={handleChange} required className="input" />
              <input type="text" name="pincode" placeholder="Pincode" onChange={handleChange} required className="input" />

              <input type="number" name="totalTables" placeholder="Total Tables" onChange={handleChange} required className="input" />
            </div>
          </div>

          {/* Submit Button */}
          <button
            type="submit"
            disabled={loading}
            className="w-full py-3 rounded-xl text-white font-semibold text-lg shadow-md transition-all bg-gradient-to-r from-[#D4AF37] to-[#FFD700] hover:opacity-90"
          >
            {loading ? "Registering..." : "Register Restaurant"}
          </button>

          {/* Message */}
          {message && (
            <p
              className={`text-center mt-4 font-medium ${
                message.includes("Successfully") ? "text-green-600" : "text-red-600"
              }`}
            >
              {message}
            </p>
          )}
        </form>
      </div>
    </section>
  );
}
